-- Seed for chapter 4.4 onward. Written by tools/make_seed.py. Do not edit by hand.
-- requires: views, dropped
-- loaded-if: select 1 from views where visitor like '5eed%' limit 1
-- Dates are relative to the day you load it: the seven days ending yesterday.
-- Markers: visitor codes start with 5eed, a few views have the referrer host seed.example,
-- and dropped rows have 777777 microseconds in the time.
begin;
set local time zone 'UTC';
delete from views where visitor like '5eed%';
delete from dropped where (extract(microseconds from at)::bigint % 1000000) = 777777;
commit;
